// Existing DISCOMOD runtime_env API compatibility.
const fs = require('fs');
const path = require('path');
const ENV_FILE = path.resolve(process.cwd(), '.env');
const EDITABLE_KEYS = new Set([
    'DISCORD_TOKEN','CLIENT_ID','CLIENT_SECRET','OPENAI_API_KEY','ANTHROPIC_API_KEY',
    'GROQ_API_KEY','GEMINI_API_KEY','MISTRAL_API_KEY','DEEPSEEK_API_KEY','XAI_API_KEY',
    'DASHBOARD_ENABLED','DASHBOARD_PORT','DASHBOARD_REDIRECT_URI','DASHBOARD_SESSION_SECRET',
    'DASHBOARD_PUBLIC_URL','DASHBOARD_TRUST_PROXY','DASHBOARD_BOT_PERMISSIONS',
    'TURNSTILE_SITE_KEY','TURNSTILE_SECRET_KEY','AI_MODEL_CLAUDE','AI_MODEL_OPENAI',
    'AI_MODEL_GROQ','AI_MODEL_GEMINI','AI_MODEL_MISTRAL','AI_MODEL_DEEPSEEK','AI_MODEL_GROK'
]);
const _envListeners = new Set();
function envProviders() {
    const found = new Map();
    for (const [k,v] of Object.entries(process.env)) {
        const m = /^PROVIDER_([A-Z0-9_]+)_(URL|KEY|MODEL)$/.exec(k);
        if (!m) continue;
        const name = m[1].toLowerCase();
        const row = found.get(name) || {name, baseUrl:'', key:'', model:''};
        if (m[2] === 'URL') row.baseUrl = String(v || '');
        if (m[2] === 'KEY') row.key = String(v || '');
        if (m[2] === 'MODEL') row.model = String(v || '');
        found.set(name,row);
    }
    return [...found.values()];
}
function envMasked(v) {
    const s=String(v||''); if(!s) return '';
    if(s.length<=6) return '*'.repeat(s.length);
    return s.slice(0,3)+'*'.repeat(Math.max(3,s.length-6))+s.slice(-3);
}
function list() {
    return [...EDITABLE_KEYS].sort().map(key => ({key, set: !!process.env[key], masked: envMasked(process.env[key])}));
}
function isAllowedKey(key) { return EDITABLE_KEYS.has(String(key||'').toUpperCase()); }
function explainDenied(key) { return `Environment key ${String(key||'').toUpperCase()} is not editable.`; }
function onChange(fn) { if (typeof fn === 'function') _envListeners.add(fn); return () => _envListeners.delete(fn); }
function _parseEnvFile() {
    try { return require('dotenv').parse(fs.readFileSync(ENV_FILE,'utf8')); }
    catch { return {}; }
}
function reload() {
    const parsed=_parseEnvFile(); const changed=[];
    for (const key of EDITABLE_KEYS) {
        const next = parsed[key]; const prev = process.env[key];
        if (next !== undefined && next !== prev) { process.env[key]=next; changed.push(key); }
        if (next === undefined && prev !== undefined && key.startsWith('PROVIDER_')===false) { continue; }
    }
    for (const fn of _envListeners) { try { fn(changed); } catch {} }
    return {ok:true, changed};
}
function _persistEnv(values) {
    const current={..._parseEnvFile(),...values};
    const lines=Object.entries(current).map(([k,v])=>`${k}=${JSON.stringify(String(v))}`);
    if (fs.existsSync(ENV_FILE)) { try { fs.copyFileSync(ENV_FILE, ENV_FILE+'.bak'); } catch {} }
    fs.writeFileSync(ENV_FILE, lines.join('\n')+'\n','utf8');
}
function setEnv(key,value) {
    const k=String(key||'').toUpperCase().trim(); if(!isAllowedKey(k)) return {ok:false,error:explainDenied(k)};
    const created = process.env[k] === undefined; process.env[k]=String(value??'');
    try { _persistEnv({[k]:process.env[k]}); } catch(e) { return {ok:false,error:`Failed to write .env: ${e.message}`}; }
    for (const fn of _envListeners) { try { fn([k]); } catch {} }
    return {ok:true,key:k,created};
}
function unset(key) {
    const k=String(key||'').toUpperCase().trim(); if(!isAllowedKey(k)) return {ok:false,error:explainDenied(k)};
    const existed=process.env[k] !== undefined; delete process.env[k];
    try {
        const parsed=_parseEnvFile(); delete parsed[k];
        if (fs.existsSync(ENV_FILE)) fs.copyFileSync(ENV_FILE, ENV_FILE+'.bak');
        fs.writeFileSync(ENV_FILE,Object.entries(parsed).map(([a,b])=>`${a}=${JSON.stringify(String(b))}`).join('\n')+'\n','utf8');
    } catch(e) { return {ok:false,error:`Failed to write .env: ${e.message}`}; }
    for (const fn of _envListeners) { try { fn([k]); } catch {} }
    return {ok:true,key:k,removed:existed};
}
function init() { return reload(); }
module.exports.envProviders = envProviders;
module.exports.list = list;
module.exports.isAllowedKey = isAllowedKey;
module.exports.explainDenied = explainDenied;
module.exports.onChange = onChange;
module.exports.reload = reload;
